\section{From the notes

blocks.t:
The two dotted lines touching the closest points are the margin lines;
the points touching them are the support vectors. The middle line is
the hyperplane.

\boxed{
\begin{aligned}
\min_{w,b}\quad & \tfrac{1}{2} \|w\|^{2}

\text{s.t.}\quad & y_i (w^{T}x_i + b) \ge 1, \qquad i=1,\dots,n .
\end{aligned}}

\boxed{
\begin{aligned}
\max_{\alpha}\quad & \sum_{i=1}^{n}\alpha_i-\frac12\sum_{i=1}^{n}\sum_{j=1}^{n}
\alpha_i\alpha_j y_i y_j \langle x_i,x_j\rangle

\text{s.t.}\quad & \alpha_i \ge 0,\qquad \sum_i \alpha_i y_i = 0 .
\end{aligned}}
